     "time": "08-24 12:17",
     "ts": 1787545036,
     "summary": "新西兰总理拉克森在一份声明中表示，新西兰政府将于当天在议会提交法案，禁止16岁以下青少年使用社交媒体。据悉，该法案将要求社交媒体平台采取合理措施核实用户年龄，包括利用现有账户信息、面部识别技术及数字身份证件等进行认证。此外，法案还提议对违规平台处以最高达其全球营收10%的罚款。 （文章来源：财联社）",
